window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8a0b15fdd5e5cfc3"]={"versions": [{"id": "FIG-8a0b15fdd5e5cfc3", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Komponentendiagramm / Port-Schnittstellen-Übersicht im AUTOSAR-Architekturkontext. Das Diagramm modelliert die softwareseitige Kopplung zwischen Anwendungs-Software-Komponenten (SW-Cs) und dem BSW-Modul ECU State Manager (EcuM) über das AUTOSAR Virtual Functional Bus (VFB)- bzw. RTE-Port-Konzept.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten und Ports:</p>\n<ul class=\"fig-list\">\n<li><strong>SW-C (Software Components)</strong>: Mehrere Instanzen bzw. SW-Cs (angedeutet durch vertikale Auslassungspunkte <code>...</code>), jeweils ausgestattet mit Ports:</li>\n<li><code>require StateRequest</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require CurrentMode</code> (Mode-Switch- oder Notification-Receiver, Winkel-Symbol)</li>\n<li><code>require CurrentState</code> (Receiver-/Required-Port, Winkel-Symbol)</li>\n<li><code>require ShutdownTarget</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require BootTarget</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require ApplicationMode</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><strong>ECU State Manager</strong>: Zentrales BSW-Modul mit korrespondierenden Ports:</li>\n<li><code>SR000</code> ... <code>SRnnn</code> (provide <code>StateRequest</code>, Ball-Symbole): Bereitstellung von Zustandsanforderungs-Schnittstellen für einzelne SW-C-Benutzer/Instanzen.</li>\n<li><code>currentMode</code> (provide <code>CurrentMode</code>, Pfeilsymbol/Provider für Modusumschaltung): Versorgt mehrere SW-Cs (gezeigt als 1:n-Verbindung zu oberer und unterer SW-C) mit aktuellen Modusinformationen.</li>\n<li><code>currentState</code> (provide <code>CurrentState</code>, Pfeilsymbol/Provider für Zustandsanzeige): Signalisiert den aktuellen EcuM-Zustand an SW-Cs.</li>\n<li><code>shutdownTarget</code> (provide <code>ShutdownTarget</code>, Ball-Symbol): Verwaltung des Shutdown-Ziels.</li>\n<li><code>bootTarget</code> (provide <code>BootTarget</code>, Ball-Symbol): Verwaltung des Boot-Ziels.</li>\n<li><code>applicationMode</code> (provide <code>ApplicationMode</code>, Ball-Symbol): Verwaltung des Anwendungsmodus.</li>\n</ul>\n<p class=\"fig-p\">Verbindungen: Gestrichelte Konnektoren verbinden komplementäre Ports (Ball/Socket bzw. Mode-Provider/Mode-User) zwischen den SW-Cs und dem ECU State Manager.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Port-Mapping-Diagramm ohne explizite zeitliche Sequenzabfolge. Dargestellt ist das Interaktionsmuster:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs richten Anforderungen bezüglich Zustand, Shutdown-Target, Boot-Target und Applikationsmodus über dedizierte Client/Server- oder Sender/Receiver-Verbindungen an den EcuM.</li>\n<li>EcuM meldet den aktuellen Zustand (<code>currentState</code>) sowie aktuelle Betriebsmodi (<code>currentMode</code>) an die abonnierten SW-Cs zurück. Die Modusmeldung <code>currentMode</code> ist als 1:n-Verteilung ausgeführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Schnittstellendefinition für die EcuM-Service-Ports in AUTOSAR Classic:</p>\n<ul class=\"fig-list\">\n<li>Für jede anfordernde SW-C ist eine eigene Instanz des State-Request-Ports (<code>SR000</code> bis <code>SRnnn</code>) bereitzustellen.</li>\n<li>EcuM muss die Ports <code>shutdownTarget</code>, <code>bootTarget</code>, <code>applicationMode</code>, <code>currentMode</code> und <code>currentState</code> für Applikationskomponenten über die RTE bereitstellen.</li>\n<li>Die RTE realisiert die 1:n-Verbindung des Modus- bzw. Benachrichtigungs-Ports <code>currentMode</code> zu allen interessierten SW-C-Empfängern.</li>\n</ul>"}, {"id": "FIG-4cad6518ddb54ffa", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Komponentendiagramm / Port-Schnittstellen-Übersicht im AUTOSAR-Architekturkontext. Das Diagramm modelliert die softwareseitige Kopplung zwischen Anwendungs-Software-Komponenten (SW-Cs) und dem BSW-Modul ECU State Manager (EcuM) über das AUTOSAR Virtual Functional Bus (VFB)- bzw. RTE-Port-Konzept.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten und Ports:</p>\n<ul class=\"fig-list\">\n<li><strong>SW-C (Software Components)</strong>: Mehrere Instanzen bzw. SW-Cs (angedeutet durch vertikale Auslassungspunkte <code>...</code>), jeweils ausgestattet mit Ports:</li>\n<li><code>require StateRequest</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require CurrentMode</code> (Mode-Switch- oder Notification-Receiver, Winkel-Symbol)</li>\n<li><code>require CurrentState</code> (Receiver-/Required-Port, Winkel-Symbol)</li>\n<li><code>require ShutdownTarget</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require BootTarget</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require ApplicationMode</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><strong>ECU State Manager</strong>: Zentrales BSW-Modul mit korrespondierenden Ports:</li>\n<li><code>SR000</code> ... <code>SRnnn</code> (provide <code>StateRequest</code>, Ball-Symbole): Bereitstellung von Zustandsanforderungs-Schnittstellen für einzelne SW-C-Benutzer/Instanzen.</li>\n<li><code>currentMode</code> (provide <code>CurrentMode</code>, Pfeilsymbol/Provider für Modusumschaltung): Versorgt mehrere SW-Cs (gezeigt als 1:n-Verbindung zu oberer und unterer SW-C) mit aktuellen Modusinformationen.</li>\n<li><code>currentState</code> (provide <code>CurrentState</code>, Pfeilsymbol/Provider für Zustandsanzeige): Signalisiert den aktuellen EcuM-Zustand an SW-Cs.</li>\n<li><code>shutdownTarget</code> (provide <code>ShutdownTarget</code>, Ball-Symbol): Verwaltung des Shutdown-Ziels.</li>\n<li><code>bootTarget</code> (provide <code>BootTarget</code>, Ball-Symbol): Verwaltung des Boot-Ziels.</li>\n<li><code>applicationMode</code> (provide <code>ApplicationMode</code>, Ball-Symbol): Verwaltung des Anwendungsmodus.</li>\n</ul>\n<p class=\"fig-p\">Verbindungen: Gestrichelte Konnektoren verbinden komplementäre Ports (Ball/Socket bzw. Mode-Provider/Mode-User) zwischen den SW-Cs und dem ECU State Manager.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Port-Mapping-Diagramm ohne explizite zeitliche Sequenzabfolge. Dargestellt ist das Interaktionsmuster:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs richten Anforderungen bezüglich Zustand, Shutdown-Target, Boot-Target und Applikationsmodus über dedizierte Client/Server- oder Sender/Receiver-Verbindungen an den EcuM.</li>\n<li>EcuM meldet den aktuellen Zustand (<code>currentState</code>) sowie aktuelle Betriebsmodi (<code>currentMode</code>) an die abonnierten SW-Cs zurück. Die Modusmeldung <code>currentMode</code> ist als 1:n-Verteilung ausgeführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Schnittstellendefinition für die EcuM-Service-Ports in AUTOSAR Classic:</p>\n<ul class=\"fig-list\">\n<li>Für jede anfordernde SW-C ist eine eigene Instanz des State-Request-Ports (<code>SR000</code> bis <code>SRnnn</code>) bereitzustellen.</li>\n<li>EcuM muss die Ports <code>shutdownTarget</code>, <code>bootTarget</code>, <code>applicationMode</code>, <code>currentMode</code> und <code>currentState</code> für Applikationskomponenten über die RTE bereitstellen.</li>\n<li>Die RTE realisiert die 1:n-Verbindung des Modus- bzw. Benachrichtigungs-Ports <code>currentMode</code> zu allen interessierten SW-C-Empfängern.</li>\n</ul>"}, {"id": "FIG-108079b23a5c4b0c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Komponentendiagramm / Port-Schnittstellen-Übersicht im AUTOSAR-Architekturkontext. Das Diagramm modelliert die softwareseitige Kopplung zwischen Anwendungs-Software-Komponenten (SW-Cs) und dem BSW-Modul ECU State Manager (EcuM) über das AUTOSAR Virtual Functional Bus (VFB)- bzw. RTE-Port-Konzept.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten und Ports:</p>\n<ul class=\"fig-list\">\n<li><strong>SW-C (Software Components)</strong>: Mehrere Instanzen bzw. SW-Cs (angedeutet durch vertikale Auslassungspunkte <code>...</code>), jeweils ausgestattet mit Ports:</li>\n<li><code>require StateRequest</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require CurrentMode</code> (Mode-Switch- oder Notification-Receiver, Winkel-Symbol)</li>\n<li><code>require ShutdownTarget</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require BootTarget</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><code>require ApplicationMode</code> (Client-/Required-Port, Socket-Symbol)</li>\n<li><strong>ECU State Manager</strong>: Zentrales BSW-Modul mit korrespondierenden Ports:</li>\n<li><code>SR000</code> ... <code>SRnnn</code> (provide <code>StateRequest</code>, Ball-Symbole): Bereitstellung von Zustandsanforderungs-Schnittstellen für einzelne SW-C-Benutzer/Instanzen.</li>\n<li><code>currentMode</code> (provide <code>CurrentMode</code>, Pfeilsymbol/Provider für Modusumschaltung): Versorgt mehrere SW-Cs (gezeigt als 1:n-Verbindung zu oberer und unterer SW-C) mit aktuellen Modusinformationen.</li>\n<li><code>shutdownTarget</code> (provide <code>ShutdownTarget</code>, Ball-Symbol): Verwaltung des Shutdown-Ziels.</li>\n<li><code>bootTarget</code> (provide <code>BootTarget</code>, Ball-Symbol): Verwaltung des Boot-Ziels.</li>\n<li><code>applicationMode</code> (provide <code>ApplicationMode</code>, Ball-Symbol): Verwaltung des Anwendungsmodus.</li>\n</ul>\n<p class=\"fig-p\">Verbindungen: Gestrichelte Konnektoren verbinden komplementäre Ports (Ball/Socket bzw. Mode-Provider/Mode-User) zwischen den SW-Cs und dem ECU State Manager.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Port-Mapping-Diagramm ohne explizite zeitliche Sequenzabfolge. Dargestellt ist das Interaktionsmuster:</p>\n<ul class=\"fig-list\">\n<li>SW-Cs richten Anforderungen bezüglich Zustand, Shutdown-Target, Boot-Target und Applikationsmodus über dedizierte Client/Server- oder Sender/Receiver-Verbindungen an den EcuM.</li>\n<li>EcuM meldet aktuelle Betriebsmodi (<code>currentMode</code>) an die abonnierten SW-Cs zurück. Die Modusmeldung <code>currentMode</code> ist als 1:n-Verteilung ausgeführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Schnittstellendefinition für die EcuM-Service-Ports in AUTOSAR Classic:</p>\n<ul class=\"fig-list\">\n<li>Für jede anfordernde SW-C ist eine eigene Instanz des State-Request-Ports (<code>SR000</code> bis <code>SRnnn</code>) bereitzustellen.</li>\n<li>EcuM muss die Ports <code>shutdownTarget</code>, <code>bootTarget</code>, <code>applicationMode</code> und <code>currentMode</code> für Applikationskomponenten über die RTE bereitstellen.</li>\n<li>Die RTE realisiert die 1:n-Verbindung des Modus- bzw. Benachrichtigungs-Ports <code>currentMode</code> zu allen interessierten SW-C-Empfängern.</li>\n</ul>"}], "trans": [{"from": "FIG-8a0b15fdd5e5cfc3", "to": "FIG-4cad6518ddb54ffa", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4cad6518ddb54ffa", "to": "FIG-108079b23a5c4b0c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Port <code>currentState</code> am ECU State Manager entfällt samt zugehöriger <code>provide CurrentState</code>-Schnittstelle.</li>\n<li>Port <code>require CurrentState</code> an der Software-Komponente (<code>SW-C</code>) entfällt samt Verbindung zum ECU State Manager.</li>\n</ul>"}]};
